        // Spreadsheets: the CSV / TSV round-trip (plan 3.5, js/csv.js).
        'Spreadsheet': 'Hoja de cálculo',
        'Import': 'Importar',
        'Each sheet is a CSV file any spreadsheet opens (UTF-8, accents and all). Copy as TSV puts the same rows on the clipboard, to paste straight into an open sheet.': 'Cada hoja es un archivo CSV que abre cualquier hoja de cálculo (UTF-8, con acentos y todo). Copiar como TSV pone las mismas filas en el portapapeles, para pegarlas directamente en una hoja abierta.',
        'Paste rows copied from a spreadsheet, or open a CSV file. Rows are matched to devices by id, MAC, IP or name; a row that matches none adds a device. Nothing changes until you apply it.': 'Pega filas copiadas de una hoja de cálculo o abre un archivo CSV. Las filas se emparejan con dispositivos por id, MAC, IP o nombre; una fila que no coincide con ninguno añade un dispositivo. Nada cambia hasta que lo apliques.',
        'Rows': 'Filas',
