        'Matches {n} devices by {key}: add an id or a MAC to say which.': 'Coincide con {n} dispositivos por {key}: añade un id o una MAC para indicar cuál.',
        'Nothing to find or name this device by: map a name, an address or an id.': 'Nada con qué encontrar o nombrar este dispositivo: asigna un nombre, una dirección o un id.',
        'Another row sets {field} to {value}.': 'Otra fila pone {field} en {value}.',
        'A port without a switch is left out.': 'Un puerto sin switch se deja fuera.',
        'No device called {name}.': 'Ningún dispositivo se llama {name}.',
        '{name} names more than one device.': '{name} nombra a más de un dispositivo.',
        '{mac} and {ip} are on different interfaces of {name}: add the interface to say which.': '{mac} y {ip} están en interfaces distintas de {name}: añade la interfaz para indicar cuál.',
        '{name} has {ports} ports: port {port} is past its faceplate and shows as a port overflow.': '{name} tiene {ports} puertos: el puerto {port} queda más allá de sus puertos y se marca como desbordamiento de puertos.',
