        'Asset tag {tag} is on {n} devices: {names}.': 'La etiqueta de activo {tag} está en {n} dispositivos: {names}.',
        'The notes on {names} look like they hold a password. Whoever gets this can read it: take it out first, or keep it somewhere else.': 'Las notas de {names} parecen contener una contraseña. Quien reciba esto puede leerla: quítala antes, o guárdala en otro sitio.',
        'Show them': 'Mostrarlos',
        'This looks like a password. Notes travel with every link, file and report of this network.': 'Esto parece una contraseña. Las notas viajan con cada enlace, archivo e informe de esta red.',
        'Asset tag {tag} is on more than one network kept here. Which one?': 'La etiqueta de activo {tag} está en más de una red guardada aquí. ¿Cuál?',
        'No device with asset tag {tag} is kept in this browser.': 'En este navegador no hay ningún dispositivo con la etiqueta de activo {tag}.',
        'Labels': 'Etiquetas',
        'Print': 'Imprimir',
        'Sized for 62 × 29 mm labels, one per page. A cable gets two: one for each end.': 'Tamaño para etiquetas de 62 × 29 mm, una por página. Un cable lleva dos: una para cada extremo.',
        'Give a device an asset tag first: its label is the tag and its QR code.': 'Primero dale a un dispositivo una etiqueta de activo: su etiqueta impresa es eso y su código QR.',
        'Select devices or cables to print their labels.': 'Selecciona dispositivos o cables para imprimir sus etiquetas.',
        'Devices without an asset tag left out: {n}': 'Dispositivos sin etiqueta de activo que se dejan fuera: {n}',
        'Cables without a label left out: {n}': 'Cables sin etiqueta que se dejan fuera: {n}',
        'Give a cable a label first: its label is what is printed.': 'Primero pon una etiqueta al cable: lo que se imprime es su etiqueta.',
        'Gateway {gw} is on {node}, which is retired.': 'La puerta de enlace {gw} está en {node}, que está retirado.',
        '{ip}: found on {node}, which is retired.': '{ip}: está en {node}, que está retirado.',
        // The Findings tab, accepted findings and the report rework (p2-report).
        'No findings: every check passes on the map as drawn.': 'Sin hallazgos: todas las comprobaciones pasan en el mapa tal como está dibujado.',
        'Known and kept on purpose. They no longer count, and the report lists them with their reason.': 'Conocidos y mantenidos a propósito. Ya no cuentan, y el informe los lista con su motivo.',
        'Accepted: {n}': 'Aceptados: {n}',
        'Not raised at the moment.': 'No aparece en este momento.',
        'Reason: {reason}': 'Motivo: {reason}',
