        'Accept…': 'Aceptar…',
        'Keep this finding as known, with a reason. It stays listed but no longer counts.': 'Mantén este hallazgo como conocido, con un motivo. Sigue en la lista pero ya no cuenta.',
        'Why is this accepted? The reason is kept with the network and printed in the report.\n\n{finding}': '¿Por qué se acepta? El motivo se guarda con la red y se imprime en el informe.\n\n{finding}',
        'Accept a finding': 'Aceptar un hallazgo',
        'Accept': 'Aceptar',
