        // Port names, labels and access VLANs (js/model.js, document v6).
        'Port names': 'Nombres de los puertos',
        'Prefix, e.g. Gi1/0/': 'Prefijo, p. ej. Gi1/0/',
        'Prefix': 'Prefijo',
        'The number port 1 is called': 'El número del puerto 1',
        'Port labels and VLANs': 'Etiquetas y VLAN de los puertos',
        'Label': 'Etiqueta',
        'Port {port} → {name}': 'Puerto {port} → {name}',
