        'Network documentation report': 'Отчёт о документировании сети',
        'Site not named': 'Объект не назван',
        'Print / Save as PDF': 'Печать / Сохранить в PDF',
        'Summary': 'Сводка',
        'Devices': 'Устройства',
        'Connections': 'Соединения',
