        'Start at': 'Начать с',
        '{n} counts up, {n:02} pads it to two digits, {name} is the current name. With Find filled, only that text in each name is replaced.': '{n} считает по возрастанию, {n:02} дополняет нулями до двух цифр, {name} — текущее имя. Если заполнено «Найти», в каждом имени заменяется только этот текст.',
        'No subnet is declared yet. Declare one on the Subnets tab first.': 'Подсети ещё не объявлены. Сначала объявите подсеть на вкладке Subnets.',
        'Preview': 'Предпросмотр',
        // The search box over the map and the table (js/query.js).
        'Search, e.g. type:camera': 'Поиск, напр. type:camera',
        'Search the map and table': 'Поиск по карте и таблице',
        'Plain words match any field. Narrow with name:, type:, ip: (an address or a network such as 10.0.0.0/24), mac:, vlan:, switch: and has:finding. Put - in front of a word to leave it out. Enter frames the matches on the map.': 'Обычные слова ищутся во всех полях. Уточняйте с помощью name:, type:, ip: (адрес или сеть, например 10.0.0.0/24), mac:, vlan:, switch: и has:finding. Поставьте - перед словом, чтобы исключить его. Enter показывает совпадения на карте.',
        'Clear the search': 'Очистить поиск',
        'Zoom to matches': 'Показать совпадения',
        'Select every device that matches (on the Cables tab, every cable)': 'Выделить все совпадающие устройства (на вкладке «Кабели» — все кабели)',
