        'No rows match the search.': 'Нет строк, подходящих под поиск.',
        // Add devices and blocks (js/add.js)
        'Add devices': 'Добавить устройства',
        '＋ Add devices…': '＋ Добавить устройства…',
        'Count what you are adding. Each one is connected to what you pick under More options and gets the next free address there.': 'Посчитайте, что добавляете. Каждое устройство подключается к тому, что выбрано в разделе «Ещё параметры», и получает там следующий свободный адрес.',
        'More options': 'Ещё параметры',
        'Name pattern': 'Шаблон имени',
        '{n} counts up, {n:02} pads it to two digits, {type} is the kind of device. Numbering carries on after the names already on the map.': '{n} — счётчик, {n:02} дополняет его нулями до двух цифр, {type} — вид устройства. Нумерация продолжается после имён, которые уже есть на карте.',
        'Connect to': 'Подключить к',
        'One fewer': 'На один меньше',
