        'Label {label} is on {n} cables: {cables}.': 'Маркировка {label} стоит на кабелях ({n}): {cables}.',
        'Asset tag {tag} is on {n} devices: {names}.': 'Инвентарный номер {tag} стоит на устройствах ({n}): {names}.',
        'The notes on {names} look like they hold a password. Whoever gets this can read it: take it out first, or keep it somewhere else.': 'Похоже, в заметках {names} записан пароль. Его сможет прочитать любой, кто это получит: уберите его заранее или храните в другом месте.',
        'Show them': 'Показать их',
