        'Paste rows copied from a spreadsheet, or open a CSV file. Rows are matched to devices by id, MAC, IP or name; a row that matches none adds a device. Nothing changes until you apply it.': '表計算ソフトからコピーした行を貼り付けるか、CSV ファイルを開いてください。各行は id、MAC、IP、名前の順でデバイスと照合され、どれにも一致しない行はデバイスとして追加されます。適用するまで何も変わりません。',
